{"type": "file", "encoding": "utf-8", "name": "TierManager.cs", "path": "Assets/Scripts/DynamicDifficulty/TierManager.cs", "size": 5622, "sha": "8d0791f6d42126bbb26eb051f606edd44c80e4d0", "content": "using GameEvents;
using Match3D.Utility;
using Player;
using System.Data;
using UnityEngine;

namespace DynamicDifficulty
{
    public static class TierManager
    {
        const string AssignedFirstBucketKey = "AssignedFirstBucket";
        const string DynamicDifficultyTierKey = "DynamicDifficultyTier";
        const int MinTier = -2;
        const int MaxTier = 5;
        static int RetryTierOffset = 0;

        public static void Initialize()
        {
            GameEventsManager.SafeAddListener(OnGameEvent);
        }

        private static void OnGameEvent(GameEvent gameEvent)
        {
            switch(gameEvent.GameEventType)
            {
                case GameEventType.LevelEnded:
                    var levelEndedEvent = (LevelEnded)gameEvent;
                    WinHistory.AddResult(levelEndedEvent.EndLevelInformation.Won, levelEndedEvent.EndLevelInformation.ClicksPerMinute);

                    var totalGames = WinHistory.GetTotalGames();
                    if (totalGames == 10)
                        ApplyInitialBucketing();
                    //else if (totalGames > 10 && !IsFirstBucketAssigned())
                    //    ApplyInitialBucketing();
                    else if (totalGames > 10)
                        ApplyPromotions();

                    if (levelEndedEvent.EndLevelInformation.Won)
                        RetryTierOffset = 0;

                    var last10CPM = WinHistory.GetCPMHistoryTenGames();
                    AnalyticsManager.Instance.SetUserProperty("Last10CPM", last10CPM.ToString());
                    AnalyticsManager.Instance.SetUserProperty("LastLevel", levelEndedEvent.EndLevelInformation.Level.ToString());
                    break;
            }
        }

        public static int GetRetryTierOffset()
        {
            return RetryTierOffset;
        }

        public static int GetCurrentDynamicDifficultyTier()
        {
            return PlayerPrefs.GetInt(DynamicDifficultyTierKey, 0);
        }

        public static bool IsFirstBucketAssigned()
        {
            return PlayerPrefs.GetInt(AssignedFirstBucketKey, 0) == 1;
        }

        public static void SetFirstBucketAssigned(bool assigned)
        {
            PlayerPrefs.SetInt(AssignedFirstBucketKey, assigned ? 1 : 0);
            PlayerPrefs.Save();
        }

        public static int ApplyTierChange(int delta)
        {
            var currentTier = GetCurrentDynamicDifficultyTier();
            currentTier += delta;
            currentTier = Mathf.Clamp(currentTier, MinTier, MaxTier);
            PlayerPrefs.SetInt(DynamicDifficultyTierKey, currentTier);

            WinHistory.ResetTierWinHistory();

            PlayerPrefs.Save();

            AnalyticsManager.Instance.SetUserProperty("DynamicDifficultyTier", currentTier.ToString());

            return currentTier;
        }

        public static void ApplyInitialBucketing()
        {
            var last10CPM = WinHistory.GetCPMHistoryTenGames();
            var currentTier = GetCurrentDynamicDifficultyTier();

            int newTier;
            switch (last10CPM)
            {
                case var cpm when cpm > 90.0f:
                    newTier = 1;
                    break;
                default:
                    newTier = 0;
                    break;
            }

            ApplyTierChange(newTier - currentTier);

            SetFirstBucketAssigned(true);

            GameEventsManager.SafeSendEvent(new DynamicDifficultyTierAssigned(newTier, last10CPM));
        }

        public static void ApplyPromotions()
        {
            var rules = WinRateRule.Defaults;
            var currentTier = GetCurrentDynamicDifficultyTier();

            foreach(var rule in rules)
            {
                if(currentTier < rule.TierMin || currentTier > rule.TierMax)
                {
                    continue;
                }

                var isGreaterThanRule = rule.ComparisonType == RuleComparisonType.GreaterThanOrEqualTo || rule.ComparisonType == RuleComparisonType.GreaterThan;
                var winHistory = isGreaterThanRule ? WinHistory.GetWorstTierWinRatePossible(rule.NumGames) : WinHistory.GetBestTierWinRatePossible(rule.NumGames);
                bool ruleApplies = false;

                switch(rule.ComparisonType)
                {
                    case RuleComparisonType.GreaterThanOrEqualTo:
                        ruleApplies = winHistory >= rule.WinRate;
                        break;
                    case RuleComparisonType.GreaterThan:
                        ruleApplies = winHistory > rule.WinRate;
                        break;
                    case RuleComparisonType.LessThanOrEqualTo:
                        ruleApplies = winHistory <= rule.WinRate;
                        break;
                    case RuleComparisonType.LessThan:
                        ruleApplies = winHistory < rule.WinRate;
                        break;
                }

                if (ruleApplies)
                {
                    Debug.Log($"Applying Dynamic Difficulty Tier Change: {rule}");
                    var newTier = ApplyTierChange(rule.TierChange);

                    // If we are being demoted
                    if(rule.TierChange < 0)
                    {
                        // Make sure to offset for current level
                        RetryTierOffset--;
                    }

                    GameEventsManager.SafeSendEvent(new DynamicDifficultyTierChanged(rule.TierChange, newTier, rule));
                    break;
                }
            }
        }
    }
